ewlabel{tab:cross_model_bcs}{{5}{13}{Cross-model BCS-controlled FewRel accuracy. High-BCS accuracy converges to $\approx $51\% regardless of model, while low-BCS accuracy reflects model capacity differences. The confusability gap ($\Delta $, in pp) is 77--87\% as large on Llama-3.1-8B as on Qwen3-32B}{table.caption.43}{}}

ewlabel{tab:error_taxonomy}{{6}{13}{Intra-batch substitution (IntraSub) and missed-entity rates by BCS bin, with Spearman $ho $ computed over $n=154$ individual batches (RE) and $n=148$ batches (NER). NER has 4 BCS bins; RE has 5}{table.caption.44}{}}

